package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// NodeState represents the local state of a node
type NodeState struct {
	localCounter uint64
	lastSeq      uint64
}

var nodes []*NodeState
var seqKV maelstrom.SeqKV
var myID int = 0
var nodeIDs []int

func main() {
	go.Run(func(ctx context.Context, handle msgHandler) error {
		handle.Init(nodeIDs) // Get IDs from init message

		// Create a global key for the counter - use my node ID + "counter"
		counterKey := fmt.Sprintf("counter_%d", myID)

		// Start using seq-kv
		seqKV = maelstrom.NewSeqKV(ctx, 0, nodes[0])

		for {
			if msg, err := handle.Recv(); err != nil {
				return err
			} else if msg.Type == "init" {
				handle.Reply(msg.ID(), "init", "ok")
			} else {
				err = handle.Handle(msg.Body)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error handling message: %v\n", err)
				}
			}
		}
	})

	return nil
}

// msgHandler represents the handler for messages from maelstrom library
type msgHandler interface {
	Init([]int) error
	Handle(json.RawMessage) error
	Reply(msgID, typ string, body json.RawMessage) error
	Send(ctx context.Context, dest int, body json.RawMessage, replyMsgID int) error
	Recv() (*maelstrom.Msg, error)
}

// Node handles all messages
type Node struct {
	ctx   context.Context
	handle msgHandler
	id    int
	state *NodeState
}

func newNode(ctx context.Context, handle maelstrom.NodeHandle) *Node {
	n := &Node{ctx: ctx, handle: handle, state: &NodeState{}}

	// Initialize from seq-kv (should be 0 for grow-only counter)
	seqKV, err := maelstrom.NewSeqKV(ctx, n.id, nil)
	if err != nil {
		return nil
	}

	// Read initial value for this node
	n.state.localCounter, _ = seqKV.Read(ctx, "counter")

	return n
}

// Handle handles a message from the cluster
func (n *Node) Handle(body json.RawMessage) error {
	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"` // for add, this is msg_id to reply to
		Delta int64   `json:"delta,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	switch msg.Type {
	case "add":
		return n.handleAdd(msg.MsgID, msg.Delta)
	case "read":
		return n.handleRead(msg.MsgID)
	default:
		return fmt.Errorf("unknown message type: %s", msg.Type)
	}
}

// handleAdd processes an add request
func (n *Node) handleAdd(msgID int, delta int64) error {
	if delta < 0 {
		fmt.Fprintf(os.Stderr, "negative delta not allowed\n")
		return fmt.Errorf("delta must be non-negative")
	}

	// Use atomic compare-and-swap on seq-kv to ensure grow-only
	// Each node has its own counter in seq-kv
	counterKey := fmt.Sprintf("counter_%d", n.id)

	// Compare and swap: try to increment from current value
	// We use a simple approach: read, then write new value
	ctx := context.Background()

	for {
		val, err := seqKV.ReadInt(ctx, counterKey)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading counter: %v\n", err)
			return err
		}

		newVal := val + uint64(delta)
		err = seqKV.CompareAndSwap(ctx, counterKey, val, newVal)
		if err == nil {
			// Successfully updated
			n.state.localCounter = newVal
			break
		}
		// CAS failed, retry
	}

	// Reply to the request
	return n.handleReply(msgID, "add_ok", nil)
}

// handleRead processes a read request
func (n *Node) handleRead(msgID int) error {
	ctx := context.Background()

	// Read the current value from seq-kv (global counter)
	val, err := seqKV.ReadInt(ctx, fmt.Sprintf("counter_%d", n.id))
	if err != nil {
		fmt.Fprintf(os.Stderr, "error reading counter: %v\n", err)
		return err
	}

	// Reply with the value
	return n.handleReply(msgID, "read_ok", []byte(fmt.Sprintf("%d", val)))
}

// handleReply sends a reply to a request
func (n *Node) handleReply(msgID int, typ string, body json.RawMessage) error {
	reply := json.RawMessage(`{"type": "` + typ + `"}`)
	if len(body) > 0 {
		reply = append(reply, `,"in_reply_to":"` + fmt.Sprintf("%d", msgID) + `","value":"`)
	} else {
		reply = append(reply, `,"in_reply_to":"` + fmt.Sprintf("%d", msgID) + `")`)
	}

	if len(body) > 0 {
		bodyVal := json.RawMessage(`"` + body + `"}`)
		reply = append(reply[:len(reply)-2], bodyVal...)
	}

	return n.handle.Send(nil, int64(n.id), reply, msgID)
}

// NewSeqKV creates a new seq-kv client for this node
func (n *Node) NewSeqKV(ctx context.Context) maelstrom.SeqKV {
	return maelstrom.NewSeqKV(ctx, n.id, nil)
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

var myID = 0
var nodeIDs []int
var seqKV maelstrom.SeqKV
var mu sync.Mutex

// handle is the msgHandler interface from maelstrom library
type handle interface {
	Init(nodeIDs []int) error
	Reply(msgID int, typ string, body json.RawMessage) error
	Send(ctx context.Context, dest int, destBody json.RawMessage, replyMsgID int) error
	Recv() (*maelstrom.Msg, error)
}

// handleAdd handles add messages
type handleAdd struct {
	msgID      int
	delta uint64
}

func (h *handleAdd) Handle(body json.RawMessage) error {
	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"`
		Delta int64  `json:"delta,omitempty"`
	}
	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	switch msg.Type {
	case "add":
		if msg.Delta < 0 {
			return fmt.Errorf("delta must be non-negative")
		}
		// Atomically increment the global counter using seq-kv
		val, _, err := seqKV.ReadInt(context.Background(), "counter", &handle)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading counter: %v\n", err)
			return err
		}

		newVal := val + uint64(msg.Delta)

		// Try to atomically write the new value
		_, ok, err := seqKV.Write(context.Background(), "counter", newVal, &handle)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error writing counter: %v\n", err)
			return err
		}

		h.msgID = msg.MsgID
		h.delta = newVal
		return nil
	case "read":
		val, _, err := seqKV.ReadInt(context.Background(), "counter", &handle)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading counter: %v\n", err)
			return err
		}

		h.msgID = msg.MsgID
		h.delta = val
		return nil
	default:
		return fmt.Errorf("unknown message type: %s", msg.Type)
	}
}

// handleAddOK returns "add_ok" with in_reply_to field
func (h *handleAdd) Reply(msgID int, typ string, body json.RawMessage) error {
	reply := json.RawMessage(`{"type": "` + typ + `"}`)
	if len(body) > 0 {
		inReplyToStr := strconv.FormatInt(int64(msgID), 10)
		inReplyToVal := ""
		var err error
		if typ == "add_ok" {
			inReplyToVal = body
		}
		reply, err = json.Marshal(map[string]interface{}{
			"type":         typ,
			"in_reply_to":  inReplyToStr,
			"value":         inReplyToVal,
		})
		if err != nil {
			return err
		}
	}

	return h.send(nil, reply)
}

// handleSend sends a message to another node
func (h *handleAdd) Send(ctx context.Context, dest int, destBody json.RawMessage, replyMsgID int) error {
	reply := json.RawMessage(`{"type": "` + typ + `"}`)
	if len(destBody) > 0 {
		reply = append(reply, `,"in_reply_to":"` + strconv.FormatInt(int64(replyMsgID), 10) + `",")`)
	}

	// For now, we just send the message to our own node ID (self-reply)
	// In a real implementation, we would broadcast or use a pub/sub pattern
	return h.send(ctx, reply)
}

func (h *handleAdd) send(ctx context.Context, destBody json.RawMessage) error {
	reply := json.RawMessage(`{"type": "` + typ + `"}`)
	if len(destBody) > 0 {
		inReplyToStr := strconv.FormatInt(int64(replyMsgID), 10)
		reply = append(reply, `,"in_reply_to":"` + inReplyToStr + `",")`)
	}

	return h.send(ctx, reply)
}

func (h *handleAdd) handleRecv() (*maelstrom.Msg, error) {
	return h.recv()
}

// NewNode creates a new node handler
type NodeHandler struct {
	handle  interface{}
	seqKV   maelstrom.SeqKV
	myID    int
	nodeIDs []int
}

func main() {
	// Initialize the Go module and run the node
	go.Run(func(ctx context.Context, handle maelstrom.NodeHandle) error {
		// Get the init message to learn our IDs
		if msg, err := handle.Recv(); err != nil {
			return err
		} else if msg.Type == "init" {
			nodeIDs = msg.NodeIDs
			myID = msg.ID()

			// Initialize seq-kv with a fresh key for the counter
			seqKV, err := maelstrom.NewSeqKV(ctx, 0, nil)
			if err != nil {
				return err
			}

			// Read initial counter value (should be 0 if no prior writes)
			_, _, err = seqKV.ReadInt(ctx, "counter", &handle)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error reading counter: %v\n", err)
				return err
			}

			// Store reference to handle for later use
			node := &NodeHandler{
				handle:  handle,
				seqKV:   seqKV,
				myID:    myID,
				nodeIDs: nodeIDs,
			}

			for {
				msg, err := node.handleRecv()
				if err != nil {
					return err
				}

				switch msg.Type {
				case "init":
					handle.Reply(msg.ID(), "init", `{"type": "init_ok"}`)
				default:
					node.addHandle.Handle(msg.Body)
				}
			}
		} else {
			return fmt.Errorf("unexpected init message: %v\n", msg.Type)
		}
	})

	return nil
}

