	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"`
		Delta int64  `json:"delta,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	// For grow-only counter, each node has its own counter in seq-kv
	counterKey := "counter"

	// Compare-and-swap to atomically increment
	// Read the current value
	val, _, err := n.seqKV.ReadInt(ctx, counterKey)
	if err != nil {
		return fmt.Errorf("error reading counter: %w", err)
	}

	newVal := val + uint64(msg.Delta)

	// Use compare-and-swap to atomically update
	_, ok, err := n.seqKV.CompareAndSwap(ctx, counterKey, val, newVal)
	if err != nil {
		return fmt.Errorf("error in CAS: %w", err)
