	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	// Read the current counter value from seq-kv
	val, _, err := n.seqKV.ReadInt(ctx, "counter")
	if err != nil {
		return fmt.Errorf("error reading counter: %w", err)
	}

	msg.Reply = func(msgID int) error {
		inReplyTo := fmt.Sprintf("%d", msgID)
		valueStr := fmt.Sprintf("%d", val)
		replyBody := `{"type": "read_ok"}`
