	MessageBody
	Value any `json:"value"`
}

// seqWriteOKBody represents the response body for a seq-kv write_ok message
type seqWriteOKBody struct {
	MessageBody
}

// seqCASOKBody represents the response body for a seq-kv cas_ok message
type seqCASOKBody struct {
	MessageBody
	Succeeded bool `json:"succeeded"`
}

// node handles all messages for the cluster
type node struct {
	id       string
	nodeIDs  []string
	seqKV    *maelstrom.KV
	localVal int // my own counter value, synced with seq-kv
}

func newNode(ctx context.Context, n *node) *node {
	return n
}

// nodeHandle handles the init message and returns a handler that processes add/read requests
func (n *node) handleAdd(ctx context.Context, body json.RawMessage) error {
	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"`
		Delta int64  `json:"delta,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	// Each node maintains its own counter in seq-kv to ensure grow-only semantics
	counterKey := fmt.Sprintf("counter_%d", n.id)

	// Use compare-and-swap to atomically increment
	// Read current value
	val, err := n.seqKV.ReadInt(ctx, counterKey)
	if err != nil {
		return fmt.Errorf("error reading counter: %w", err)
	}

	newVal := val + int(msg.Delta)

	// CAS: try to update from old to new value
	_, ok, err := n.seqKV.CompareAndSwap(ctx, counterKey, val, newVal, true)
	if err != nil {
		return fmt.Errorf("error in CAS: %w", err)
	}

	// Reply with add_ok and the new value
	return json.Unmarshal([]byte(fmt.Sprintf(`{"type":"add_ok","in_reply_to":%d,"value":%d}`, msg.MsgID, newVal)), &msg)
}

func (n *node) handleRead(ctx context.Context, body json.RawMessage) error {
	var msg struct {
		Type  string `json:"type"`
		MsgID int    `json:"msg_id,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	// Read the current counter value from seq-kv
	val, err := n.seqKV.ReadInt(ctx, fmt.Sprintf("counter_%d", n.id))
	if err != nil {
		return fmt.Errorf("error reading counter: %w", err)
	}

	// Reply with read_ok and the value
	return json.Unmarshal([]byte(fmt.Sprintf(`{"type":"read_ok","in_reply_to":%d,"value":%d}`, msg.MsgID, val)), &msg)
}

func (n *node) handleInit(ctx context.Context, body json.RawMessage) error {
	var msg struct {
		Type     string `json:"type"`
		NodeID   int    `json:"node_id,omitempty"`
		NodeIDs  []int  `json:"node_ids,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		return err
	}

	n.id = fmt.Sprintf("%d", msg.NodeID)
	n.nodeIDs = msg.NodeIDs
	n.seqKV, _ = maelstrom.NewSeqKV(ctx, n.id, nil)

	// Read initial value (should be 0 if no prior writes)
	n.localVal, _ = n.seqKV.ReadInt(ctx, fmt.Sprintf("counter_%d", n.id))
	return nil
}

func main() {
	go.Run(func(ctx context.Context, node *maelstrom.Node) error {
		nodeID := "local"

		// Register init handler
		node.Handle("init", func(msg maelstrom.Message) error {
			var body map[string]any
			if err := json.Unmarshal(msg.Body, &body); err != nil {
				return err
			}

			nodeID = fmt.Sprintf("%d", body["node_id"].(int))
			nodeIDs := make([]int, 0)
			if nids, ok := body["node_ids"].([]interface{}); ok {
				for _, ni := range nids {
					nodeIDs = append(nodeIDs, int(ni.(float64)))
				}
			}

			return nil
		})

		// Register add handler
		node.Handle("add", func(msg maelstrom.Message) error {
			var body map[string]any
			if err := json.Unmarshal(msg.Body, &body); err != nil {
				return err
			}

			msgID := int(body["msg_id"].(float64))
			delta := int(body["delta"].(float64))

			// Create a unique key per node for grow-only counter
			counterKey := fmt.Sprintf("counter_%d", nodeID)

			// Read current value
			val, err := node.seqKV.ReadInt(ctx, counterKey)
			if err != nil {
				return err
			}

			newVal := val + delta

			// CAS to atomically increment
			_, ok, err := node.seqKV.CompareAndSwap(ctx, counterKey, val, newVal, true)
			if err != nil {
				return err
			}

			body["in_reply_to"] = msgID
			body["value"] = newVal

			return json.Marshal(msg)
		})

		// Register read handler
		node.Handle("read", func(msg maelstrom.Message) error {
			var body map[string]any
			if err := json.Unmarshal(msg.Body, &body); err != nil {
				return err
			}

			msgID := int(body["msg_id"].(float64))
			counterKey := fmt.Sprintf("counter_%d", nodeID)

			val, err := node.seqKV.ReadInt(ctx, counterKey)
			if err != nil {
				return err
			}

			body["in_reply_to"] = msgID
			body["value"] = val

			return json.Marshal(msg)
		})

		// Initialize seq-kv
		node.seqKV, _ = maelstrom.NewSeqKV(ctx, nodeID, nil)

		// Run the main message loop
		return nil
	})

	return nil
}

